import {drawMon} from './art.mjs';
const TAU=Math.PI*2,cache=new Map(),rand=n=>{const x=Math.sin(n*91.37)*17373;return x-Math.floor(x)};
export function drawBattleScene(c,w,h,theme='garden',time=0,{weather='',reducedMotion=false}={}){const key=[w,h,theme].join(':');let base=cache.get(key);if(!base){base=document.createElement('canvas');base.width=w;base.height=h;const x=base.getContext('2d'),den=theme==='cavern',night=theme==='moon',palette=den?['#17242d','#22303b','#263941']:night?['#192e3e','#24424c','#2f5056']:['#3f7165','#548371','#67917b'];x.fillStyle=palette[0];x.fillRect(0,0,w,h);
 const sky=x.createLinearGradient(0,0,0,h*.4);sky.addColorStop(0,den?'#101b29':night?'#10283c':'#416c7d');sky.addColorStop(1,palette[0]);x.fillStyle=sky;x.fillRect(0,0,w,h*.42);
 for(let layer=0;layer<3;layer++){x.fillStyle=den?['#12212b','#1a2c34','#294038'][layer]:['#29495c','#365b65','#426f68'][layer];x.beginPath();x.moveTo(0,h*.4);for(let px=0;px<=w+30;px+=28)x.lineTo(px,h*(.19+layer*.055)-rand(px+layer*37)*h*.11);x.lineTo(w,h*.5);x.lineTo(0,h*.5);x.fill()}
 for(let y=Math.floor(h*.35);y<h;y+=8)for(let px=0;px<w;px+=8){x.fillStyle=palette[(Math.floor(rand(px+y*13)*3))];x.globalAlpha=.3+rand(px*3+y)*.25;x.fillRect(px,y,8,8)}x.globalAlpha=1;
 x.fillStyle=den?'#46505b':night?'#73918d':'#d0cbb1';x.beginPath();x.ellipse(w*.5,h*.59,w*.4,h*.27,0,0,TAU);x.fill();x.strokeStyle=den?'#7c8a91':'#efe4bc';x.lineWidth=3;x.stroke();x.fillStyle=den?'#3c4654':night?'#637e7c':'#bbbca0';x.beginPath();x.ellipse(w*.5,h*.59,w*.385,h*.25,0,0,TAU);x.fill();
 x.save();x.translate(w*.5,h*.59);x.scale(1,.58);x.strokeStyle=den?'#8498a333':'#e9e0b366';x.lineWidth=2;x.beginPath();x.arc(0,0,w*.12,0,TAU);x.moveTo(-w*.37,0);x.lineTo(w*.37,0);x.stroke();x.fillStyle=den?'#71838c':'#d3d3ae';x.beginPath();x.arc(0,0,8,0,TAU);x.fill();x.restore();
 for(let i=0;i<16;i++){const px=rand(i+7)*w,py=h*(.36+rand(i+77)*.59);if(Math.abs(px-w*.5)<w*.41)continue;if(den){x.fillStyle=i%2?'#6fa9a9':'#a29bc6';x.beginPath();x.moveTo(px,py-15);x.lineTo(px+6,py);x.lineTo(px-7,py);x.fill()}else{x.fillStyle='#254e48';x.fillRect(px-10,py-4,21,10);x.fillStyle='#789a6a';for(let j=0;j<5;j++)x.fillRect(px-11+j*5,py-8-rand(i+j)*8,4,10)}}
 if(cache.size>8)cache.clear();cache.set(key,base)}c.imageSmoothingEnabled=false;c.drawImage(base,0,0);
 if(!reducedMotion)for(let i=0;i<17;i++){const px=(rand(i*7)*w+Math.sin(time*.4+i)*10+w)%w,py=(rand(i+45)*h-time*(theme==='cavern'?3:5)+h*4)%h;c.globalAlpha=.15+Math.sin(time+i)*.1;c.fillStyle=theme==='cavern'?'#a6e7e2':'#e3ecb1';c.fillRect(px,py,1.5,1.5)}c.globalAlpha=1;
 if(weather){c.save();c.globalAlpha=.18;c.fillStyle=weather==='sun'?'#ffd17b':weather==='rain'?'#1d4b78':weather==='sand'?'#bd9665':'#c5e9e8';c.fillRect(0,0,w,h);if(!reducedMotion){c.globalAlpha=.5;c.strokeStyle=weather==='rain'?'#b7d6ec':'#e4e5c8';c.lineWidth=1;for(let i=0;i<50;i++){const px=(rand(i+23)*w+time*(weather==='sand'?35:4))%w,py=(rand(i+51)*h+time*(weather==='rain'?140:22))%h;c.beginPath();c.moveTo(px,py);c.lineTo(px+(weather==='rain'?-3:2),py+(weather==='rain'?9:1));c.stroke()}}c.restore()}
}
export function drawCondition(c,mon,x,y,size,time,reduced){if(!mon.status&&!Object.values(mon.stages||{}).some(n=>n))return;c.save();const status=mon.status;if(status){const color=({burn:'#f5aa62',paralysis:'#f3dc77',poison:'#cf91de',toxic:'#ce75c5',sleep:'#acc4e2',freeze:'#a7e4ec'})[status];c.fillStyle=color;c.globalAlpha=.22;c.beginPath();c.ellipse(x,y+size*.28,size*.3,size*.1,0,0,TAU);c.fill();c.globalAlpha=.9;for(let i=0;i<3;i++){const phase=reduced?.4:(time*.6+i*.33)%1,px=x+Math.sin(i*2.4+time)*size*.22,py=y-size*.2-phase*size*.4;c.fillStyle=color;if(status==='sleep'){c.font='9px PixelLocal';c.fillText('z',px,py)}else if(status==='paralysis'){c.fillRect(px,py,2,7);c.fillRect(px-2,py+3,5,2)}else c.fillRect(px,py,3,3)}}const boost=Object.values(mon.stages||{}).reduce((a,b)=>a+b,0);if(boost){c.strokeStyle=boost>0?'#a6e3bc':'#d5a2b3';c.globalAlpha=.6;c.lineWidth=1;c.beginPath();c.ellipse(x,y+size*.3,size*.34,size*.1,0,0,TAU);c.stroke()}c.restore()}
